public sealed record Money(decimal Amount, string Currency);

var a = new Money(10m, "USD");
var b = new Money(10m, "USD");

Console.WriteLine(a == b);                 // True: compared by value
Console.WriteLine(ReferenceEquals(a, b));  // False: still two objects
Console.WriteLine(a);                      // Money { Amount = 10, Currency = USD }

var set = new HashSet<Money> { a, b };     // one element: equal hashes and equality
var (amount, currency) = a;                // positional records deconstruct

var price = new Money(10m, "USD");
var discounted = price with { Amount = 8m };   // new object; price is unchanged

public sealed record Cart(string Id, List<string> Items);
var c1 = new Cart("c1", new List<string> { "mug" });
var c2 = c1 with { };                          // shallow copy
c2.Items.Add("tee");                           // c1.Items changed too
Console.WriteLine(c1 == c2);                   // True: same list reference
Console.WriteLine(new Cart("c1", new() { "mug" }) == new Cart("c1", new() { "mug" })); // False: different lists
